sp_widget.client_script:
function($scope, $location) {
  $scope.goTo = function(id) {
    //$location.url("?id=" + id);
		window.open("?id=" + id, '_blank');
  };

$scope.goToPage = function(id) {
    $location.url("?id=" + id);
};


	// Estado inicial (pode ser null, true ou false)
$scope.isLowercase = null;

// Escuta evento do rootScope para atualizar o estado
$scope.$root.$on('toggleCaseEvent', function(event, isLowercase) {
  $scope.isLowercase = isLowercase;
});


}

sp_widget.css:
.fiscal-widget-container {
  font-family: 'Roboto Flex', sans-serif !important;
  font-weight: 400; 
  font-style: normal;
  display: flex;
  flex-wrap: wrap;
	justify-content: center;
  padding: 2rem;
  gap: 2rem;
  margin: 0 auto 3rem;
  max-width:100%;

.fiscal-card {
  flex: 1 1 calc(33.333% - 2rem); /* 3 por linha com espaçamento */
  min-width: 280px; /* evita ficar pequeno demais */
  max-width: 350px; /* seu valor original */
  height: 220px;
  background: white;
  border-radius: 8px;
  box-shadow: 0 2px 6px rgba(0, 0, 0, 0.1);
  text-align: center;
  padding-top: 20px;
  cursor: pointer;
  transition: transform 0.2s;
  overflow: hidden;
  display: flex;
  flex-direction: column;
  align-items: center;
}

.fiscal-card:hover {
  transform: scale(1.05);
}

.fiscal-card img {
  height: 10rem;
  margin-top: 10px;
  object-fit: contain;
}

.fiscal-label {
  background-color: #e2e5f3;
  border-bottom-right-radius: 0.8rem;
  border-top-right-radius: 0.8rem;
  padding: 8px 12px;
  font-weight: 500;
  margin-bottom: 10px;
  display: inline-block;
  align-self: flex-start; /* alinha à esquerda dentro do card */
  margin-top: 4.5rem;
  font-size: 2.0rem;

}

  .lowercase-text {
  text-transform: lowercase;
}

.uppercase-text {
  text-transform: uppercase;
}


	/* Telas Maiores (desk grandes > 1200px) vai manter 3 colunas, mas com espaço*/
 @media (min-width: 1201px) {
  .fiscal-widget-container {
    padding: 3rem;
    gap: 3rem;
  }

    .fiscal-card {
    flex-basis: calc(33.333% - 3rem);
      max-width: 400px;
  }
}

 /* Telas médias (Tablets deitados, desk menores) vai ter 2 colunas */
  @media (max-width: 1200px) {
    .fiscal-widget-container {
      padding: 1.5rem;
      gap: 1.5rem;
    }

    .fiscal-card {
      flex: 1 1 calc(50% - 1.5rem); /* 2 cards por linha */
      max-width: 45%;
    }
  }

  /* Telas pequenas (tablets deitados 601px - 900px) - Ainda vai ter 2 colunas, mas menores */
  @media (max-width: 900px) {
    .fiscal-widget-container {
      padding: 1rem;
      gap: 1rem;
      margin-left: 0;
      margin-bottom: 5rem;
    }

    .fiscal-card {
      flex: 1 1 calc(50% - 1rem);
      max-width: calc(50% - 1rem);
      height: 200px;

      .fiscal-card img {
        height: 8rem;
      }
      .fiscal-label {
        font-size: 2rem;
        padding: 8px 12px;
        margin-top: 3rem;
      }
    }

  }
}
